edits.oldText:
// Call LLM out-of-band via direct API (no session involvement)
async function callLlmOutOfBand(
  question: string,
  systemPrompt: string,
  maxTokens: number,
  ctx: Parameters<Parameters<typeof pi.on>[1]>[1],
): Promise<string | null> {
  const llmConfig = getLlmConfig(ctx);
  if (!llmConfig) {
    return null;
  }

  const { provider, baseUrl, key, model } = llmConfig;

  try {
    if (provider === "anthropic") {
      const url = baseUrl || "https://api.anthropic.com/v1/messages";
      const resp = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": key,
          "anthropic-version": "2023-06-01",
        },
        body: JSON.stringify({
          model,
          max_tokens: maxTokens,
          system: systemPrompt,
          messages: [{ role: "user", content: question }],
        }),
      });

      if (!resp.ok) {
        console.error(`Anthropic API error: ${resp.status}`);
        return null;
      }

      const data = (await resp.json()) as {
        content: Array<{ type: string; text: string }>;
      };
      return data.content.find((c) => c.type === "text")?.text ?? null;
    }

    if (provider === "openai") {
      const url = baseUrl || "https://api.openai.com/v1/chat/completions";
      const resp = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${key}`,
        },
        body: JSON.stringify({
          model,
          max_tokens: maxTokens,
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: question },
          ],
        }),
      });

      if (!resp.ok) {
        console.error(`OpenAI API error: ${resp.status}`);
        return null;
      }

      const data = (await resp.json()) as {
        choices: Array<{ message: { content: string } }>;
      };
      return data.choices[0]?.message?.content ?? null;
    }
  } catch (err) {
    console.error("LLM call failed:", err);
  }

  return null;
}

