content.text:
/**
 * Quick Chat — Out-of-band Q&A for pi
 *
 * Calls the LLM in a separate process so responses NEVER enter
 * the current session's context window.
 *
 * Usage:
 *   /chat "帮我翻译这段话"    → LLM answer, zero context pollution
 *   ?你的问题               → Prefix shortcut
 *   /quick calc 3*7         → Built-in utilities (no LLM)
 *   /quick date             → Current time
 *   /quick help             → Show help
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { env } from "node:process";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";

export default function (pi: ExtensionAPI) {
  // Read API key from pi's models.json config
  function readModelsJson(): { provider: string; baseUrl: string; key: string } | null {
    const modelsPath = join(homedir(), ".pi", "agent", "models.json");
    if (!existsSync(modelsPath)) return null;

    try {
      const content = readFileSync(modelsPath, "utf-8");
      const config = JSON.parse(content) as {
        providers?: Record<string, { baseUrl?: string; apiKey?: string; api?: string }>;
      };

      if (!config.providers) return null;

      // Find the first provider with a non-placeholder apiKey
      for (const [name, provider] of Object.entries(config.providers)) {
        if (provider.apiKey && provider.apiKey !== "ollama") {
          return {
            provider: name,
            baseUrl: provider.baseUrl ?? "",
            key: provider.apiKey,
          };
        }
      }
    } catch {
      // File parse error
    }

    return null;
  }

  // Get provider + API key from pi's current model configuration
  function getLlmConfig(ctx: Parameters<Parameters<typeof pi.on>[1]>[1]): { provider: string; baseUrl: string; key: string; model: string } | null {
    // Priority 1: models.json config
    const modelsJsonConfig = readModelsJson();
    if (modelsJsonConfig) {
      const model = ctx.model;
      return {
        provider: modelsJsonConfig.provider,
        baseUrl: modelsJsonConfig.baseUrl,
        key: modelsJsonConfig.key,
        model: model?.id ?? "Qwen3.6-Plus-DogFooding",
      };
    }

    // Priority 2: ctx.modelRegistry
    const model = ctx.model;
    if (!model) return null;

    const provider = model.provider;
    const modelId = model.id;

    const modelRegistry = ctx.modelRegistry;
    if (!modelRegistry) return null;

    const allModels = modelRegistry.getAllModels?.() ?? [];
    const matched = allModels.find(
      (m) => m.provider === provider && m.id === modelId
    );

    if (matched) {
      const providerKey = (matched as any).apiKey
        || (matched as any).providerApiKey;
      if (providerKey) {
        return {
          provider,
          baseUrl: (matched as any).baseUrl ?? "",
          key: providerKey,
          model: modelId,
        };
      }
    }

    // Priority 3: fallback to env
    if (env.ANTHROPIC_API_KEY) {
      return { provider: "anthropic", baseUrl: "", key: env.ANTHROPIC_API_KEY, model: modelId };
    }
    if (env.OPENAI_API_KEY) {
      return { provider: "openai", baseUrl: "", key: env.OPENAI_API_KEY, model: modelId };
    }

    return null;
  }

  // Call LLM out-of-band via direct API (no session involvement)
  async function callLlmOutOfBand(
    question: string,
    systemPrompt: string,
    maxTokens: number,
    ctx: Parameters<Parameters<typeof pi.on>[1]>[1],
  ): Promise<string | null> {
    const llmConfig = getLlmConfig(ctx);
    if (!llmConfig) {
      return null;
    }

    const { provider, baseUrl, key, model } = llmConfig;

    try {
      // Use OpenAI Chat Completions API format for all providers (most universal compatibility)
      const url = baseUrl
        ? (baseUrl.includes('/chat/completions') || baseUrl.includes('/v1/chat'))
          ? baseUrl
          : baseUrl.includes('/anthropic')
            ? baseUrl.replace('/anthropic', '/openai') + '/v1/chat/completions'
            : `${baseUrl}/v1/chat/completions`
        : "https://api.openai.com/v1/chat/completions";

      const resp = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${key}`,
        },
        body: JSON.stringify({
          model,
          max_tokens: maxTokens,
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: question },
          ],
        }),
      });

      if (!resp.ok) {
        const errBody = await resp.text().catch(() => "");
        console.error(`LLM API error: ${resp.status} ${errBody}`);
        throw new Error(`API 错误 (HTTP ${resp.status}): ${errBody || resp.statusText}`);
      }

      const data = (await resp.json()) as {
        choices?: Array<{ message?: { content?: string }; finish_reason?: string }>;
        error?: { message?: string };
      };

      if (data.error) {
        console.error(`LLM API error: ${data.error.message}`);
        throw new Error(`API 错误: ${data.error.message}`);
      }

      return data.choices?.[0]?.message?.content ?? null;
    } catch (err) {
      // Re-throw so the handler can show the actual error
      throw err;
    }

  // ============================================================
  // /chat "question" - Quick Q&A, out-of-band (RECOMMENDED)
  // Uses direct API call — zero session involvement.
  // ============================================================

  pi.registerCommand("chat", {
    description: "Quick Q&A without touching session context",
    handler: async (args, ctx) => {
      if (!args || args.trim() === "") {
        ctx.ui.notify("用法: /chat <你的问题>", "warning");
        return;
      }

      const question = args.trim();
      ctx.ui.setStatus("quick-chat", "💬 正在回答...");

      let answer: string | null = null;
      try {
        answer = await callLlmOutOfBand(
          question,
          "你是一个有帮助的助手。请用中文回答。回答简洁，最多3-5句话。",
          512,
          ctx,
        );
      } catch (err) {
        ctx.ui.setStatus("quick-chat", undefined);
        const msg = err instanceof Error ? err.message : String(err);
        ctx.ui.notify(`❌ ${msg}`, "error");
        return;
      }

      ctx.ui.setStatus("quick-chat", undefined);

      if (answer) {
        ctx.ui.notify(answer, "info");
      } else {
        ctx.ui.notify("⚠️ 未检测到 API key。请检查 ~/.pi/agent/models.json 配置，或设置 ANTHROPIC_API_KEY / OPENAI_API_KEY 环境变量。", "error");
      }
    },
  });

  // ============================================================
  // Input interception: ? prefix for quick chat
  // IMPORTANT: pi may still record the raw input in the session
  // before this handler runs. If that's the case, use /chat instead.
  // ============================================================

  pi.on("input", async (event, ctx) => {
    if (event.source !== "interactive") return;

    // ?prefix for quick chat (but not ?? which is bash history)
    if (event.text.startsWith("?") && !event.text.startsWith("??")) {
      const question = event.text.slice(1).trim();
      if (!question) return { action: "continue" };

      // Show immediate feedback
      ctx.ui.setStatus("quick-chat", "💬 " + question);

      // Fire-and-forget: don't block the input loop
      (async () => {
        try {
          const answer = await callLlmOutOfBand(
            question,
            "你是一个有帮助的助手。请用中文简洁回答，最多2-3句话。",
            256,
            ctx,
          );

          ctx.ui.setStatus("quick-chat", undefined);

          if (answer) {
            ctx.ui.notify(answer, "info");
          } else {
            ctx.ui.notify("⚠️ 未检测到 API key，无法回答。", "warning");
          }
        } catch (err) {
          ctx.ui.setStatus("quick-chat", undefined);
          const msg = err instanceof Error ? err.message : String(err);
          ctx.ui.notify(`❌ ${msg}`, "error");
        }
      })();

      // Skip agent processing — the question is handled out-of-band
      return { action: "handled" };
    }

    return { action: "continue" };
  });

  // ============================================================
  // /quick - Built-in utilities (no LLM needed)
  // ============================================================

  pi.registerCommand("quick", {
    description: "Quick utilities without LLM (date, calc, help)",
    handler: async (args, ctx) => {
      if (!args) {
        ctx.ui.notify(
          "Quick utilities:\n" +
          "  /quick date       — 当前时间\n" +
          "  /quick calc 2*3   — 简单计算\n" +
          "  /chat '...'       — LLM 问答（不占上下文）\n" +
          "  ?问题             — 快捷提问",
          "info",
        );
        return;
      }

      const parts = args.split(/\s+/);
      const cmd = parts[0].toLowerCase();
      const input = parts.slice(1).join(" ");

      try {
        switch (cmd) {
          case "date":
          case "time": {
            const now = new Date();
            ctx.ui.notify(`📅 ${now.toLocaleString("zh-CN", { timeZone: "Asia/Shanghai" })}`, "info");
            break;
          }
          case "calc":
          case "math": {
            const sanitized = input.replace(/[^0-9+\-*/().%\s]/g, "");
            const result = Function(`"use strict"; return (${sanitized})`)();
            ctx.ui.notify(`🔢 ${input} = ${result}`, "info");
            break;
          }
          case "help": {
            ctx.ui.notify(
              "用法:\n" +
              "  /chat \"问题\"    — LLM 快速问答（不占上下文）\n" +
              "  ?问题           — 同上，快捷方式\n" +
              "  /quick date     — 当前时间\n" +
              "  /quick calc 2*3 — 简单计算\n" +
              "  /quick help     — 显示帮助",
              "info",
            );
            break;
          }
          default:
            ctx.ui.notify(`未知命令: ${cmd}。试试 /quick help`, "warning");
        }
      } catch (err) {
        ctx.ui.notify(`错误: ${(err as Error).message}`, "error");
      }
    },
  });
}

