export default function (pi: ExtensionAPI) {
  // Persisted selected model across /chat calls
  let selectedModel: string | null = null;

  // Read all available models from pi's models.json
  function readAvailableModels(): Array<{ provider: string; id: string; name: string; baseUrl: string; apiKey: string; api?: string }> {
    const modelsPath = join(homedir(), ".pi", "agent", "models.json");
    if (!existsSync(modelsPath)) return [];

    try {
      const content = readFileSync(modelsPath, "utf-8");
      const config = JSON.parse(content) as {
        providers?: Record<string, {
          baseUrl?: string;
          apiKey?: string;
          api?: string;
          models?: Array<{ id: string; name?: string }>;
        }>;
      };

      if (!config.providers) return [];

      const models: Array<{ provider: string; id: string; name: string; baseUrl: string; apiKey: string; api?: string }> = [];
      for (const [providerName, provider] of Object.entries(config.providers)) {
        if (provider.models) {
          for (const m of provider.models) {
            models.push({
              provider: providerName,
              id: m.id,
              name: m.name || m.id,
              baseUrl: provider.baseUrl ?? "",
              apiKey: provider.apiKey ?? "",
              api: provider.api,
            });
          }
        }
      }
      return models;
    } catch {
      return [];
    }
  }

  // Read API key from pi's models.json config

// Get provider + API key from pi's current model configuration
function getLlmConfig(ctx: Parameters<Parameters<typeof pi.on>[1]>[1], modelOverride?: string): { provider: string; baseUrl: string; key: string; model: string; api?: string } | null {
  const allModels = readAvailableModels();

  // If a specific model is requested, find it in models.json
  if (modelOverride) {
    const matched = allModels.find(
      (m) => m.id.toLowerCase() === modelOverride.toLowerCase()
        || m.name?.toLowerCase().includes(modelOverride.toLowerCase())
        || `${m.provider}/${m.id}`.toLowerCase().includes(modelOverride.toLowerCase())
    );
    if (matched && matched.apiKey) {
      return {
        provider: matched.provider,
        baseUrl: matched.baseUrl,
        key: matched.apiKey,
        model: matched.id,
        api: matched.api,
      };
    }
    // Model not found — return null so the caller can show an error
    return null;
  }

  // Priority 1: use selected model
  if (selectedModel) {
    const matched = allModels.find(
      (m) => m.id === selectedModel || `${m.provider}/${m.id}` === selectedModel
    );
    if (matched && matched.apiKey) {
      return {
        provider: matched.provider,
        baseUrl: matched.baseUrl,
        key: matched.apiKey,
        model: matched.id,
        api: matched.api,
      };
    }
  }

  // Priority 2: first available model from models.json
  if (allModels.length > 0) {
    const first = allModels[0];
    if (first.apiKey) {
      return {
        provider: first.provider,
        baseUrl: first.baseUrl,
        key: first.apiKey,
        model: first.id,
        api: first.api,
      };
    }
  }

  // Priority 3: ctx.modelRegistry
  const model = ctx.model;
  if (!model) return null;

  const provider = model.provider;
  const modelId = model.id;

  const modelRegistry = ctx.modelRegistry;
  if (!modelRegistry) return null;

  const registryModels = modelRegistry.getAllModels?.() ?? [];
  const registryMatched = registryModels.find(
    (m) => m.provider === provider && m.id === modelId
  );

  if (registryMatched) {
    const providerKey = (registryMatched as any).apiKey
      || (registryMatched as any).providerApiKey;
    if (providerKey) {
      return {
        provider,
        baseUrl: (registryMatched as any).baseUrl ?? "",
        key: providerKey,
        model: modelId,
      };
    }
  }

  // Priority 4: fallback to env
  if (env.ANTHROPIC_API_KEY) {
    return { provider: "anthropic", baseUrl: "", key: env.ANTHROPIC_API_KEY, model: modelId };
  }
  if (env.OPENAI_API_KEY) {
    return { provider: "openai", baseUrl: "", key: env.OPENAI_API_KEY, model: modelId };
  }

  return null;
}

